// 首屏 Hero：名字 + 头衔 + 简介 + CTA
// 文案统一在 src/site.config.ts 的 hero 中维护
import { site } from '../site.config';

const { hero } = site;
---

<section class="hero">
  <div class="container hero-inner">
    <p class="eyebrow hero-eyebrow fade-up">{hero.eyebrow}</p>

    <h1 class="hero-title fade-up fade-up-1">
      {hero.intro}
      <span class="hero-name">{hero.name}</span>
      <br />
      {hero.titlePrefix}
      <span class="accent-underline">{hero.highlight}</span>。
    </h1>

    <p class="hero-desc fade-up fade-up-2">{hero.description}</p>

    <div class="hero-actions fade-up fade-up-3">
      <a href={hero.primaryCta.href} class="btn btn-primary">{hero.primaryCta.label}</a>
      <a href={hero.secondaryCta.href} class="btn btn-outline">{hero.secondaryCta.label}</a>
    </div>

    <dl class="hero-meta fade-up fade-up-4">
      {
        hero.meta.map((meta) => (
          <div class="meta-item">
            <dt class="eyebrow meta-label">{meta.label}</dt>
            <dd>
              {meta.href ? (
                <a href={meta.href} class="text-link">{meta.value}</a>
              ) : (
                meta.value
              )}
            </dd>
          </div>
        ))
      }
    </dl>
  </div>
</section>

<style>
  .hero {
    padding-top: clamp(72px, 12vw, 140px);
    padding-bottom: var(--space-section);
  }

  .hero-eyebrow {
    margin-bottom: 28px;
  }

  .hero-title {
    font-size: clamp(38px, 7vw, 76px);
    font-weight: 600;
    letter-spacing: -0.03em;
    line-height: 1.12;
    max-width: 16em;
  }

  .hero-name {
    position: relative;
    white-space: nowrap;
  }

  .hero-name::before {
    content: "";
    position: absolute;
    inset: auto -10px -4px -10px;
    height: 40%;
    background: var(--accent-soft);
    border-radius: var(--radius-sm);
    z-index: -1;
  }

  .accent-underline {
    color: var(--accent);
  }

  .hero-desc {
    margin-top: 36px;
    max-width: 560px;
    font-size: clamp(16px, 2vw, 19px);
    color: var(--text-secondary);
    line-height: 1.9;
  }

  .hero-actions {
    margin-top: 44px;
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
  }

  .hero-meta {
    margin-top: 72px;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 32px;
    max-width: 640px;
  }

  .meta-label {
    color: var(--text-tertiary);
    margin-bottom: 6px;
  }

  .meta-item dd {
    font-size: var(--text-md);
    font-weight: 500;
  }

  @media (max-width: 640px) {
    .hero-meta {
      grid-template-columns: 1fr;
      gap: 20px;
    }
  }
</style>
---
// 作品展示区块：从 content collection 读取项目
// 项目内容在 src/content/projects/*.md 中维护
import { getCollection } from 'astro:content';
import ProjectCard from './ProjectCard.astro';

const projects = (await getCollection('projects')).sort(
  (a, b) => (b.data.year || '').localeCompare(a.data.year || ''),
);
---

<section id="work" class="section work">
  <div class="container">
    <div class="section-head">
      <span class="eyebrow">01 / Work</span>
      <h2 class="section-title">精选作品</h2>
    </div>

    {
      projects.length > 0 ? (
        <div class="work-grid">
          {
            projects.map((project) => (
              <ProjectCard project={project} />
            ))
          }
        </div>
      ) : (
        <p class="empty-hint">
          暂无作品 — 在 <code>src/content/projects/</code> 中添加 markdown 文件即可展示。
        </p>
      )
    }
  </div>
</section>

<style>
  .work-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: clamp(28px, 4vw, 56px) clamp(24px, 3vw, 40px);
  }

  /* 首个项目跨两列（大图展示） */
  .work-grid > :first-child {
    grid-column: 1 / -1;
  }

  .work-grid > :first-child .title {
    font-size: clamp(20px, 2.5vw, 26px);
  }

  .empty-hint {
    padding: 48px;
    text-align: center;
    border: 1px dashed var(--border);
    border-radius: var(--radius-lg);
    color: var(--text-secondary);
  }

  .empty-hint code {
    font-family: var(--font-mono);
    background: var(--surface-muted);
    padding: 2px 8px;
    border-radius: var(--radius-sm);
    font-size: var(--text-sm);
  }

  /* 平板及以下单列 */
  @media (max-width: 768px) {
    .work-grid {
      grid-template-columns: 1fr;
    }
    .work-grid > :first-child {
      grid-column: auto;
    }
  }
</style>

