+     .tile-dark / .tile-dark-2 / .tile-light
+                全宽明暗瓦片：色块切换本身即分区，瓦片内 accent 自动换 Sky Blue
+   ============================================================ */
+
+:root {
+  color-scheme: light dark; /* 让滚动条 / 表单控件跟随深色模式 */
+
+  /* --- 色彩 Tokens（Apple Design） --- */
+  --bg: #ffffff;               /* 画布白 canvas */
+  --surface: #f5f5f7;          /* 羊皮纸 parchment：瓦片 / 页脚 / 弱卡片 */
+  --surface-muted: #f0f0f2;    /* 珍珠白 pearl：标签底 / 占位 */
+  --text: #1d1d1f;             /* 墨色 ink：全部正文与标题 */
+  --text-secondary: #6e6e73;   /* 次级文字（白底 ≥4.5:1） */
+  --text-tertiary: #86868b;    /* 弱文字：大号说明 / 禁用（白底 12px 慎用） */
+  --on-inverse: #f5f5f7;       /* 深色瓦片上的主文字 */
+  --on-inverse-muted: #a1a1a6; /* 深色瓦片上的次级文字 */
+  --accent: #0066cc;           /* Action Blue：唯一交互色 */
+  --accent-strong: #0071e3;    /* Focus Blue：hover / 焦点 */
+  --accent-on-dark: #2997ff;   /* Sky Link Blue：深色面上的链接与强调 */
+  --accent-soft: #e8f0fa;      /* 强调色浅底（正文引用） */
+  --border: #e8e8ed;           /* 发丝线 hairline（浅背景） */
+  --border-inverse: rgb(255 255 255 / 0.16); /* 深色面上的发丝线 */
+
+  /* 明暗瓦片（Apple 节奏：色块切换本身即分隔线） */
+  --tile-dark: #1d1d1f;
+  --tile-dark-2: #272729;
+  --tile-void: #000000;
+  --glyph-on-inverse: rgb(255 255 255 / 0.08); /* 深色面幽灵图形 */
+
+  /* --- 阴影：仅作品视觉留一处，UI chrome 无阴影 --- */
+  --shadow-product: 0 4px 14px rgb(0 0 0 / 0.12);
+  --shadow-sm: 0 4px 18px rgb(0 0 0 / 0.10);   /* 兼容旧用法，新 UI 不再依赖 */
+  --shadow-md: 0 16px 32px rgb(0 0 0 / 0.08);
+
+  /* --- 圆角（Apple 语法：胶囊 / 18px 卡片 / 11px 珍珠钮 / 8px 小工具） --- */
+  --radius-sm: 8px;
+  --radius-md: 11px;
+  --radius-lg: 18px;
+  --radius-xl: 24px;
+  --radius-pill: 999px;
+
+  /* --- 字体（SF Pro 系统栈，非 Apple 平台回退 PingFang / 微软雅黑） --- */
+  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text",
+    "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Helvetica Neue", sans-serif;
+  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;
+
+  /* --- 字号阶梯（Apple：17px 正文 / 14px 说明 / 12px 注释 / 21px 标语） --- */
+  --text-xs: 12px;
+  --text-sm: 14px;
+  --text-md: 17px;
+  --text-lg: 21px;
+
+  /* --- 布局 --- */
+  --container: 1120px;
+  --gutter: clamp(20px, 5vw, 48px);
+  --space-section: clamp(80px, 10vw, 120px);
+  --header-h: 48px;
+
+  /* --- 动效（按压反馈用缩放，苹果式） --- */
+  --ease: cubic-bezier(0.4, 0, 0.2, 1);
+  --dur: 0.24s;
+  --dur-fast: 0.12s;
+  --dur-slow: 0.6s;
+}
+
+/* --- 深色模式（整体映射 Apple 深色面） --- */
+@media (prefers-color-scheme: dark) {
+  :root {
+    --bg: #000000;
+    --surface: #1d1d1f;
+    --surface-muted: #272729;
+    --text: #f5f5f7;
+    --text-secondary: #a1a1a6;
+    --text-tertiary: #86868b;
+    --on-inverse: #f5f5f7;
+    --on-inverse-muted: #a1a1a6;
+    --accent: #2997ff;
+    --accent-strong: #0071e3;
+    --accent-on-dark: #2997ff;
+    --accent-soft: rgb(41 151 255 / 0.14);
+    --border: #424245;
+    --border-inverse: rgb(255 255 255 / 0.16);
+    --tile-dark: #1d1d1f;
+    --tile-dark-2: #272729;
+    --tile-void: #0a0a0b;
+    --glyph-on-inverse: rgb(255 255 255 / 0.1);
+    --shadow-product: 0 4px 14px rgb(0 0 0 / 0.5);
+  }
+}
+
+/* ============================================================
+   Reset & 基础
+   ============================================================ */
+*, *::before, *::after {
+  box-sizing: border-box;
+  margin: 0;
+  padding: 0;
+}
+
+html {
+  scroll-behavior: smooth;
+  -webkit-text-size-adjust: 100%;
+}
+
+body {
+  font-family: var(--font-sans);
+  font-size: var(--text-md); /* 17px 正文，Apple 节奏 */
+  line-height: 1.6;          /* 中文阅读需要比 1.47 稍松 */
+  color: var(--text);
+  background: var(--bg);
+  -webkit-font-smoothing: antialiased;
+  -moz-osx-font-smoothing: grayscale;
+  transition: background-color 0.3s var(--ease), color 0.3s var(--ease);
+}
+
+img {
+  display: block;
+  max-width: 100%;
+  height: auto;
+}
+
+a {
+  color: inherit;
+  text-decoration: none;
+  transition: color var(--dur) var(--ease);
+}
+
+button {
+  font: inherit;
+  cursor: pointer;
+  background: none;
+  border: none;
+}
+
+ul, ol {
+  list-style: none;
+}
+
+::selection {
+  background: var(--accent);
+  color: #fff;
+}
+
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 3px;
+}
+
+/* ============================================================
+   布局工具类
+   ============================================================ */
+.container {
+  width: 100%;
+  max-width: var(--container);
+  margin-inline: auto;
+  padding-inline: var(--gutter);
+}
+
+.section {
+  padding-block: var(--space-section);
+}
+
+/* 小节标签：首屏头衔 / 分区编号 / 侧栏小标题（12px 灰） */
+.eyebrow {
+  font-size: var(--text-xs);
+  font-weight: 400;
+  letter-spacing: 0.02em;
+  text-transform: uppercase;
+  color: var(--text-secondary);
+}
+
+/* 小标签：类别 / 年份 / 详情页标签（14px 胶囊 + 发丝线） */
+.tag {
+  display: inline-block;
+  font-size: var(--text-sm);
+  line-height: 1.43;
+  letter-spacing: -0.01em;
+  color: var(--text-secondary);
+  background: var(--surface-muted);
+  padding: 4px 12px;
+  border-radius: var(--radius-pill);
+  white-space: nowrap;
+}
+
+.tag-year {
+  background: transparent;
+  border: 1px solid var(--border);
+}
+
+/* Section 标题 */
+.section-head {
+  display: flex;
+  align-items: baseline;
+  gap: 18px;
+  margin-bottom: clamp(40px, 6vw, 64px);
+}
+
+.section-title {
+  font-size: clamp(30px, 4.5vw, 40px);
+  font-weight: 600;
+  letter-spacing: -0.02em;
+  line-height: 1.1;
+}
+
+/* ============================================================
+   明暗瓦片（Apple 画廊节奏）
+   tile-dark / tile-dark-2 内会本地覆盖 --accent / --border /
+   --text-secondary，让内部组件自动切到深色面语法
+   ============================================================ */
+.tile-dark {
+  background: var(--tile-dark);
+  color: var(--on-inverse);
+  --accent: var(--accent-on-dark);
+  --accent-strong: #0071e3;
+  --border: var(--border-inverse);
+  --text-secondary: var(--on-inverse-muted);
+}
+
+.tile-dark-2 {
+  background: var(--tile-dark-2);
+  color: var(--on-inverse);
+  --accent: var(--accent-on-dark);
+  --accent-strong: #0071e3;
+  --border: var(--border-inverse);
+  --text-secondary: var(--on-inverse-muted);
+}
+
+.tile-light {
+  background: var(--surface);
+  color: var(--text);
+}
+
+/* ============================================================
+   按钮
+   ============================================================ */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  gap: 8px;
+  padding: 11px 22px;
+  border-radius: var(--radius-pill);
+  font-size: var(--text-md);
+  font-weight: 400;
+  letter-spacing: -0.01em;
+  line-height: 1;
+  white-space: nowrap;
+  transition:
+    background-color var(--dur) var(--ease),
+    color var(--dur) var(--ease),
+    border-color var(--dur) var(--ease),
+    transform var(--dur-fast) var(--ease);
+}
+
+/* 蓝底白字胶囊：Apple 主 CTA */
+.btn-primary {
+  background: var(--accent);
+  color: #fff;
+}
+
+.btn-primary:hover {
+  background: var(--accent-strong);
+}
+
+.btn-primary:active {
+  transform: scale(0.98);
+}
+
+/* 白底蓝字描边胶囊：Apple 次级 CTA（Learn more） */
+.btn-outline {
+  background: var(--bg);
+  color: var(--accent);
+  border: 1px solid var(--border);
+}
+
+.btn-outline:hover {
+  border-color: var(--accent);
+  background: color-mix(in srgb, var(--accent) 6%, var(--bg));
+}
+
+.btn-outline:active {
+  transform: scale(0.98);
+}
+
+/* 深色瓦片上的主按钮：用 Focus Blue 保证白字对比度 */
+.tile-dark .btn-primary,
+.tile-dark-2 .btn-primary {
+  background: var(--accent-strong);
+}
+
+/* 文本链接：Action Blue 常显，hover 出现下划线 */
+.text-link {
+  position: relative;
+  display: inline-block;          /* 便于 padding 扩大点击面 */
+  padding: 2px 2px 4px;
+  color: var(--accent);
+  font-weight: 400;
+  text-underline-offset: 4px;
+}
+
+.text-link:hover,
+.text-link:focus-visible {
+  text-decoration: underline;
+}
+
+/* ============================================================
+   页面过渡动画
+   ============================================================ */
+@keyframes fade-up {
+  from {
+    opacity: 0;
+    transform: translateY(18px);
+  }
+  to {
+    opacity: 1;
+    transform: translateY(0);
+  }
+}
+
+.fade-up {
+  animation: fade-up 0.6s var(--ease) both;
+}
+
+.fade-up-1 { animation-delay: 0.06s; }
+.fade-up-2 { animation-delay: 0.14s; }
+.fade-up-3 { animation-delay: 0.22s; }
+.fade-up-4 { animation-delay: 0.3s; }
+
+@media (prefers-reduced-motion: reduce) {
+  html { scroll-behavior: auto; }
+  *, *::before, *::after {
+    animation-duration: 0.01ms !important;
+    transition-duration: 0.01ms !important;
+  }
+}
